// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testRegression_property() public {
        vm.warp(1000);
        vm.roll(1);

        vm.deal(address(this), 10 ether);
        (bool success1, ) = address(c).call{value: 10 ether}("");
        assertTrue(success1, "First fallback call should succeed");

        uint pastAfterFirst = c.pastBlockTime();

        vm.warp(pastAfterFirst + 1);

        (bool success2, ) = address(c).call{value: 0 ether}("");

        uint pastAfterSecond = c.pastBlockTime();

        if (success2) {
            assertTrue(pastAfterSecond > pastAfterFirst, "Buggy: pastBlockTime increased");
        } else {
            assertTrue(pastAfterSecond == pastAfterFirst, "Reference: pastBlockTime unchanged");
        }

        assertTrue(!success2 && pastAfterSecond == pastAfterFirst, "Reference behavior: second call reverts and state unchanged");
    }
}
